// Normaliza el payload de ManyChat (o de un curl de prueba en F3).
// Espera body con: { canal, subscriber_id, mensaje } o defaults seguros.

const body = $input.first().json.body || $input.first().json;

const canal = (body.canal || 'test').toLowerCase();          // 'whatsapp' | 'ig' | 'fb' | 'test'
const subId = String(body.subscriber_id || body.from || 'anon');
const leadIdentifier = `${canal}_${subId}`;                  // sessionKey para memoria
const mensajeActual = String(body.mensaje || body.text || '').trim();

if (!mensajeActual) {
  return [{ json: { skip: true, reason: 'empty_message' } }];
}

const canalLabel = canal === 'whatsapp' ? 'WhatsApp'
                 : canal === 'ig' ? 'Instagram'
                 : canal === 'fb' ? 'Facebook'
                 : 'Test';

return [{
  json: {
    skip: false,
    canal,
    canalLabel,
    subId,
    leadIdentifier,
    mensajeActual,
    firstName: body.first_name || '',
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

// Inyecta [CONTEXTO TURNO] al user message para que el LLM tenga vars dinámicas.
const data = $input.first().json;
const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });

const contextoTurno = `[CONTEXTO TURNO]
- Canal: ${data.canalLabel}
- Fecha y hora actual: ${fecha}
- Perfil del lead (si se conoce): sin clasificar
- Etapa actual: bienvenida
- Datos ya capturados: {}
- Productos ya mostrados: ninguno

[MENSAJE DEL USUARIO]
${data.mensajeActual}`;

return [{
  json: {
    ...data,
    userMessage: contextoTurno
  }
}];

// Divide la respuesta del agente por separador --- en hasta 3 partes.
const output = $input.first().json.output || '';
const partes = output.split(/^---\s*$/m)
                     .map(p => p.trim())
                     .filter(p => p.length > 0);

const [parte1 = '', parte2 = '', parte3 = ''] = partes.slice(0, 3);

return [{
  json: {
    raw: output,
    parte1,
    parte2,
    parte3,
    partes_count: partes.length
  }
}];
